Here is the problem description:
<problem_description>
The leader of some very secretive organization has decided to invite all other members to a meeting. All members of the organization live in the same town which can be represented as $$$n$$$ crossroads connected by $$$m$$$ two-directional streets. The meeting will be held in the leader's house near the crossroad $$$1$$$. There are $$$k$$$ members of the organization invited to the meeting; $$$i$$$-th of them lives near the crossroad $$$a_i$$$. All members of the organization receive the message about the meeting at the same moment and start moving to the location where the meeting is held. In the beginning of each minute each person is located at some crossroad. He or she can either wait a minute at this crossroad, or spend a minute to walk from the current crossroad along some street to another crossroad (obviously, it is possible to start walking along the street only if it begins or ends at the current crossroad). In the beginning of the first minute each person is at the crossroad where he or she lives. As soon as a person reaches the crossroad number $$$1$$$, he or she immediately comes to the leader's house and attends the meeting.Obviously, the leader wants all other members of the organization to come up as early as possible. But, since the organization is very secretive, the leader does not want to attract much attention. Let's denote the discontent of the leader as follows  initially the discontent is $$$0$$$;  whenever a person reaches the crossroad number $$$1$$$, the discontent of the leader increases by $$$c \cdot x$$$, where $$$c$$$ is some fixed constant, and $$$x$$$ is the number of minutes it took the person to reach the crossroad number $$$1$$$;  whenever $$$x$$$ members of the organization walk along the same street at the same moment in the same direction, $$$dx^2$$$ is added to the discontent, where $$$d$$$ is some fixed constant. This is not cumulative: for example, if two persons are walking along the same street in the same direction at the same moment, then $$$4d$$$ is added to the discontent, not $$$5d$$$. Before sending a message about the meeting, the leader can tell each member of the organization which path they should choose and where they should wait. Help the leader to establish a plan for every member of the organization so they all reach the crossroad $$$1$$$, and the discontent is minimized.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    CF1187G() { super(System.out); }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 15];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = read()) <= 32) if (c == -1) return -1;
            int val = 0;
            do {
                val = val * 10 + c - '0';
            } while ((c = read()) > 32);
            return val;
        }
    }

    FastScanner sc;

    public static void main(String[] args) {
        CF1187G solver = new CF1187G();
        solver.sc = new FastScanner(System.in);
        solver.run();
        solver.flush();
    }

    static final int INF = 0x3f3f3f3f;
    ArrayList<Integer>[] graph;
    int nodes, edges;
    int[] potential, level;
    int[] from, to, xorEdge;
    int[] capacity, originalCost, reducedCost;
    int[] edgeCount;

    void initialize(int n, int m) {
        nodes = n;
        edges = m;
        graph = new ArrayList[nodes];
        for (int i = 0; i < nodes; i++) graph[i] = new ArrayList<>();
        potential = new int[nodes];
        level = new int[nodes];
        from = new int[edges];
        to = new int[edges];
        xorEdge = new int[edges];
        capacity = new int[edges];
        originalCost = new int[edges];
        reducedCost = new int[edges];
        edgeCount = new int[edges];
    }

    void addEdge(int u, int v, int cap, int cost) {
        int idx = edges++;
        from[idx] = u;
        to[idx] = v;
        xorEdge[idx] = u ^ v;
        originalCost[idx] = cost;
        reducedCost[idx] = cost;
        capacity[idx] = cap;
        edgeCount[idx] = cap;
        graph[u].add(idx);
        graph[v].add(idx ^ 1);
    }

    boolean dijkstra(int source, int sink) {
        Arrays.fill(potential, INF);
        Arrays.fill(level, 0);
        potential[source] = 0;

        TreeSet<Integer> pq = new TreeSet<>((a, b) -> {
            if (potential[a] != potential[b]) return potential[a] - potential[b];
            if (level[a] != level[b]) return level[a] - level[b];
            return a - b;
        });
        pq.add(source);

        while (!pq.isEmpty()) {
            int u = pq.pollFirst();
            int nextLevel = level[u] + 1;

            for (int idx : graph[u]) {
                if (capacity[idx] <= 0) continue;
                int edgeIdx = idx >> 1;
                int cost = (idx & 1) == 0 ? reducedCost[edgeIdx] : -reducedCost[edgeIdx];
                int newDist = potential[u] + cost;
                int v = u ^ xorEdge[edgeIdx];

                if (newDist < potential[v] || (newDist == potential[v] && level[v] > nextLevel)) {
                    if (potential[v] != INF) pq.remove(v);
                    potential[v] = newDist;
                    level[v] = nextLevel;
                    pq.add(v);
                }
            }
        }
        return potential[sink] != INF;
    }

    int dfs(int u, int sink, int flow) {
        if (u == sink || flow == 0) return flow;
        int nextLevel = level[u] + 1;

        for (int idx : graph[u]) {
            if (capacity[idx] <= 0) continue;
            int edgeIdx = idx >> 1;
            int cost = (idx & 1) == 0 ? reducedCost[edgeIdx] : -reducedCost[edgeIdx];
            int v = u ^ xorEdge[edgeIdx];

            if (potential[v] == potential[u] + cost && level[v] == nextLevel) {
                int pushed = dfs(v, sink, Math.min(flow, capacity[idx]));
                if (pushed > 0) {
                    capacity[idx] -= pushed;
                    capacity[idx ^ 1] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int minCostMaxFlow(int source, int sink) {
        System.arraycopy(originalCost, 0, reducedCost, 0, edges);
        int totalCost = 0;

        while (dijkstra(source, sink)) {
            while (dfs(source, sink, INF) > 0) {}

            for (int i = 0; i < edges; i++) {
                int u = from[i], v = to[i];
                if (potential[u] != INF && potential[v] != INF) {
                    reducedCost[i] += potential[u] - potential[v];
                }
            }
        }

        for (int i = 0; i < edges; i++) {
            totalCost += originalCost[i] * (capacity[i ^ 1]);
        }
        return totalCost;
    }

    void run() {
        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();
            int c = sc.nextInt();
            int d = sc.nextInt();

            int[] specialNodes = new int[k];
            for (int i = 0; i < k; i++) {
                specialNodes[i] = sc.nextInt() - 1;
            }

            ArrayList<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                adj[u].add(v);
                adj[v].add(u);
            }

            int timeSteps = k + 1;
            int totalNodes = n * timeSteps + 1;
            int totalEdges = k + (m * 2 * k + n) * (timeSteps - 1);
            initialize(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeSteps - 1; t++) {
                    int u = i * timeSteps + t;
                    for (int neighbor : adj[i]) {
                        int v = neighbor * timeSteps + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addEdge(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeSteps - 1; t++) {
                    int u = i * timeSteps + t;
                    int v = u + 1;
                    addEdge(u, v, k, i == 0 ? 0 : c);
                }
            }

            int source = totalNodes - 1;
            for (int i = 0; i < k; i++) {
                addEdge(source, specialNodes[i] * timeSteps + 0, 1, 0);
            }

            int sink = 0 * timeSteps + timeSteps - 1;
            println(minCostMaxFlow(source, sink));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
